<?php
namespace Delnavazan\Platform\Core\Infrastructure\Repository;
final class LessonScheduleVersionRepository extends BaseRepository { public function __construct(){global $wpdb;$this->table=$wpdb->prefix.'dzn_lesson_schedule_versions';} public function current(int $lesson,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->table} WHERE lesson_id=%d AND superseded_at IS NULL".$suffix,$lesson));if(count($rows)>1)throw new \RuntimeException('Multiple current schedules');return $rows[0]??null;} public function latest(int $lesson):int{global $wpdb;return(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(version_number),0) FROM {$this->table} WHERE lesson_id=%d",$lesson));} public function history(int $lesson):array{global $wpdb;return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->table} WHERE lesson_id=%d ORDER BY version_number ASC",$lesson));} public function supersede(int $id,string $now):void{global $wpdb;$result=$wpdb->update($this->table,['superseded_at'=>$now],['id'=>$id,'superseded_at'=>null]);if(false===$result)throw new \RuntimeException($wpdb->last_error);if($result!==1)throw new \RuntimeException('Stale current schedule');} }
